"""C program skeleton used by ``c_code``; ``PRELUDE`` is a ``str.format`` template."""

PRELUDE = """/*
 * {name}: GStreamer pipeline generated by Pipelab.
 *
 * Build: gcc {file} -o {binary} $(pkg-config --cflags --libs gstreamer-1.0)
 * Run:   ./{binary}   (Ctrl+C sends EOS so files are finalised)
 *
 * Equivalent gst-launch-1.0 description:
 *   {description}
 */

#include <gst/gst.h>
#include <glib-unix.h>

typedef struct
{{
  GstPad *target;
  gchar *src_pad;
}} DynamicLink;

static GstElement *
make_element (GstElement * pipeline, const gchar * factory, const gchar * name)
{{
  GstElement *element = gst_element_factory_make (factory, name);
  if (element == NULL) {{
    g_printerr ("Element '%s' is not installed\\n", factory);
    return NULL;
  }}
  gst_bin_add (GST_BIN (pipeline), element);
  return element;
}}

static gboolean
link_pads (GstElement * src, const gchar * src_pad, GstElement * sink, const gchar * sink_pad)
{{
  if (gst_element_link_pads (src, src_pad, sink, sink_pad))
    return TRUE;
  g_printerr ("Could not link %s.%s to %s.%s\\n", GST_ELEMENT_NAME (src), src_pad,
      GST_ELEMENT_NAME (sink), sink_pad);
  return FALSE;
}}

G_GNUC_UNUSED static void
free_dynamic_link (gpointer data, GClosure * closure)
{{
  DynamicLink *link = data;
  gst_object_unref (link->target);
  g_free (link->src_pad);
  g_free (link);
}}

/* Links a "sometimes" pad (matched by name or template) once it appears. */
G_GNUC_UNUSED static void
on_pad_added (GstElement * element, GstPad * pad, gpointer user_data)
{{
  DynamicLink *link = user_data;
  GstPadTemplate *templ = gst_pad_get_pad_template (pad);
  gboolean matches = g_strcmp0 (GST_PAD_NAME (pad), link->src_pad) == 0 || (templ != NULL
      && g_strcmp0 (GST_PAD_TEMPLATE_NAME_TEMPLATE (templ), link->src_pad) == 0);
  GstCaps *offered, *accepted;
  gboolean compatible;

  if (templ != NULL)
    gst_object_unref (templ);
  if (!matches || gst_pad_is_linked (link->target))
    return;
  offered = gst_pad_query_caps (pad, NULL);
  accepted = gst_pad_query_caps (link->target, NULL);
  compatible = gst_caps_can_intersect (offered, accepted);
  gst_caps_unref (offered);
  gst_caps_unref (accepted);
  if (compatible && gst_pad_link (pad, link->target) != GST_PAD_LINK_OK)
    g_printerr ("Could not link %s.%s\\n", GST_ELEMENT_NAME (element), GST_PAD_NAME (pad));
}}

G_GNUC_UNUSED static gboolean
link_dynamic (GstElement * src, const gchar * src_pad, GstElement * sink, const gchar * sink_pad)
{{
  DynamicLink *link;
  GstPad *target = gst_element_get_static_pad (sink, sink_pad);

  if (target == NULL)
    target = gst_element_request_pad_simple (sink, sink_pad);
  if (target == NULL) {{
    g_printerr ("%s has no pad %s\\n", GST_ELEMENT_NAME (sink), sink_pad);
    return FALSE;
  }}
  link = g_new0 (DynamicLink, 1);
  link->target = target;
  link->src_pad = g_strdup (src_pad);
  g_signal_connect_data (src, "pad-added", G_CALLBACK (on_pad_added), link,
      free_dynamic_link, 0);
  return TRUE;
}}

G_GNUC_UNUSED static GstPad *
get_pad (GstElement * element, const gchar * name)
{{
  GstPad *pad = gst_element_get_static_pad (element, name);
  if (pad == NULL)
    g_printerr ("%s has no pad %s\\n", GST_ELEMENT_NAME (element), name);
  return pad;
}}

static GstElement *
build_pipeline (void)
{{
  GstElement *pipeline = gst_pipeline_new ({pipeline_name});
"""

EPILOGUE = """
static gboolean
on_message (GstBus * bus, GstMessage * message, gpointer user_data)
{
  GMainLoop *loop = user_data;
  GError *error = NULL;
  gchar *debug = NULL, *path;

  switch (GST_MESSAGE_TYPE (message)) {
    case GST_MESSAGE_ERROR:
      gst_message_parse_error (message, &error, &debug);
      path = gst_object_get_path_string (GST_MESSAGE_SRC (message));
      g_printerr ("ERROR from %s: %s\\n  %s\\n", path, error->message, debug ? debug : "");
      g_free (path);
      g_clear_error (&error);
      g_free (debug);
      g_main_loop_quit (loop);
      break;
    case GST_MESSAGE_WARNING:
      gst_message_parse_warning (message, &error, &debug);
      path = gst_object_get_path_string (GST_MESSAGE_SRC (message));
      g_printerr ("WARNING from %s: %s\\n", path, error->message);
      g_free (path);
      g_clear_error (&error);
      g_free (debug);
      break;
    case GST_MESSAGE_EOS:
      g_main_loop_quit (loop);
      break;
    default:
      break;
  }
  return G_SOURCE_CONTINUE;
}

static gboolean
on_sigint (gpointer user_data)
{
  gst_element_send_event (GST_ELEMENT (user_data), gst_event_new_eos ());
  return G_SOURCE_CONTINUE;
}

int
main (int argc, char *argv[])
{
  GstElement *pipeline;
  GMainLoop *loop;
  GstBus *bus;

  gst_init (&argc, &argv);
  pipeline = build_pipeline ();
  if (pipeline == NULL)
    return 1;

  loop = g_main_loop_new (NULL, FALSE);
  bus = gst_element_get_bus (pipeline);
  gst_bus_add_watch (bus, on_message, loop);
  gst_object_unref (bus);
  g_unix_signal_add (SIGINT, on_sigint, pipeline);

  if (gst_element_set_state (pipeline, GST_STATE_PLAYING) == GST_STATE_CHANGE_FAILURE) {
    g_printerr ("The pipeline refused to start\\n");
    gst_object_unref (pipeline);
    return 1;
  }
  g_main_loop_run (loop);

  gst_element_set_state (pipeline, GST_STATE_NULL);
  gst_object_unref (pipeline);
  g_main_loop_unref (loop);
  return 0;
}
"""
